stages.check_script:
LAMPS = [("(R)", "red"), ("(Y)", "yellow"), ("(G)", "green")]
DARK = "( )"


def lit_lamp(game, screen):
    rows = screen.rows
    game.check(len(rows) == 3, "The light must be exactly 3 lamp lines.")
    lit = []
    for row, (on, name) in zip(rows, LAMPS):
        game.check(
            row in (on, DARK), f"The {name} lamp line must be {on} or ( )."
        )
        if row == on:
            lit.append(name)
    game.check(len(lit) == 1, "Exactly one lamp must be lit.")
    return lit[0]


def check(game):
    lit_lamp(game, game.screen())
    game.check(
        game.finished, "Print the light, then end. This stage reads no input."
    )

stages.reference_program:
CYCLE = ["red"] * 3 + ["green"] * 3 + ["yellow"]
LAMPS = [("red", "(R)"), ("yellow", "(Y)"), ("green", "(G)")]


def show(color):
    for name, lit in LAMPS:
        print(lit if name == color else "( )")


turn = 0
while True:
    show(CYCLE[turn % len(CYCLE)])
    input()
    turn += 1

